CREATE TABLE favorites (
  user_id INT NOT NULL,
  zekr_id INT NOT NULL,
  PRIMARY KEY (user_id, zekr_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (zekr_id) REFERENCES azkar(id) ON DELETE CASCADE
);

SELECT category, COUNT(*) AS total FROM azkar GROUP BY category;